package dev.pocketengine.features.local.project;
import static org.junit.Assert.*;import android.app.Application;import android.content.*;import android.content.pm.*;import android.content.res.AssetFileDescriptor;import android.database.*;import android.net.Uri;import android.os.ParcelFileDescriptor;import android.provider.DocumentsContract;import dev.pocketengine.core.RunControl;import dev.pocketengine.features.local.project.android.AndroidProjectDocument;import java.io.*;import java.nio.file.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.shadows.ShadowContentResolver;
/** Actual Android ContentResolver/Document columns and raw FD, not device/provider-network proof. */
@RunWith(RobolectricTestRunner.class)@Config(sdk=35,manifest=Config.NONE,application=Application.class)
public final class AndroidProjectDocumentNativeTest {
 private Application app;private static final String AUTH="pw.document.fixture";private Uri selectedUri;private static File file;private static int flags,opens;private static long declared;private static boolean denied,directory;
 public static final class Provider extends ContentProvider{public boolean onCreate(){return true;}public String getType(Uri uri){return "application/octet-stream";}public Cursor query(Uri uri,String[] projection,String selection,String[] args,String sort){if(denied)throw new SecurityException("private provider "+uri);MatrixCursor row=new MatrixCursor(new String[]{DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_MIME_TYPE,DocumentsContract.Document.COLUMN_SIZE,DocumentsContract.Document.COLUMN_FLAGS});row.addRow(new Object[]{"asset.bin",directory?DocumentsContract.Document.MIME_TYPE_DIR:"application/octet-stream",declared,flags});return row;}public AssetFileDescriptor openAssetFile(Uri uri,String mode)throws FileNotFoundException{opens++;return new AssetFileDescriptor(ParcelFileDescriptor.open(file,ParcelFileDescriptor.MODE_READ_ONLY),0,file.length());}public Uri insert(Uri uri,ContentValues values){throw new UnsupportedOperationException();}public int delete(Uri uri,String where,String[] args){throw new UnsupportedOperationException();}public int update(Uri uri,ContentValues values,String where,String[] args){throw new UnsupportedOperationException();}}
 @Before public void create()throws Exception{app=RuntimeEnvironment.getApplication();selectedUri=Uri.parse("content://"+AUTH+"/document/selected");file=Files.createTempFile("pw-picked-document-",".bin").toFile();Files.write(file.toPath(),new byte[]{0,(byte)255,3});flags=0;opens=0;declared=3;denied=false;directory=false;ProviderInfo info=new ProviderInfo();info.authority=AUTH;info.name=Provider.class.getName();info.packageName=app.getPackageName();info.applicationInfo=app.getApplicationInfo();info.exported=true;info.grantUriPermissions=true;info.readPermission="android.permission.MANAGE_DOCUMENTS";ShadowContentResolver.registerProviderInternal(AUTH,Robolectric.buildContentProvider(Provider.class).create(info).get());ResolveInfo resolve=new ResolveInfo();resolve.providerInfo=info;Shadows.shadowOf(app.getPackageManager()).addResolveInfoForIntent(new Intent(DocumentsContract.PROVIDER_INTERFACE),resolve);assertTrue(DocumentsContract.isDocumentUri(app,selectedUri));}
 @After public void close()throws Exception{Files.deleteIfExists(file.toPath());}
 @Test public void actualDocumentProviderColumnsAndFdProduceBoundedPrivateRawBytes()throws Exception{RunControl original=new RunControl();try(var source=ProjectDocumentImport.read(new AndroidProjectDocument(app,selectedUri,original),original)){assertEquals("00ff03",source.view().getString("previewHex"));assertFalse(source.view().toString().contains(AUTH));assertEquals(1,opens);assertFalse(source.view().getBoolean("providerAtomicSnapshot"));}}
 @Test public void virtualPartialDirectoryAndDeclaredMismatchCannotBeImportedAsOrdinaryBytes()throws Exception{for(int bad:new int[]{DocumentsContract.Document.FLAG_VIRTUAL_DOCUMENT,DocumentsContract.Document.FLAG_PARTIAL}){flags=bad;RunControl control=new RunControl();assertThrows(IllegalArgumentException.class,()->ProjectDocumentImport.read(new AndroidProjectDocument(app,selectedUri,control),control));}flags=0;directory=true;RunControl dir=new RunControl();assertThrows(IllegalArgumentException.class,()->ProjectDocumentImport.read(new AndroidProjectDocument(app,selectedUri,dir),dir));assertEquals(0,opens);directory=false;declared=4;RunControl mismatch=new RunControl();assertThrows(SecurityException.class,()->ProjectDocumentImport.read(new AndroidProjectDocument(app,selectedUri,mismatch),mismatch));assertEquals(1,opens);}
 @Test public void revokedPermissionCancelledControlAndNonPickerUrisNeverFallBackOrLeakTheProviderUri()throws Exception{denied=true;RunControl control=new RunControl();SecurityException actual=assertThrows(SecurityException.class,()->ProjectDocumentImport.read(new AndroidProjectDocument(app,selectedUri,control),control));assertFalse(actual.getMessage().contains(AUTH));assertEquals(0,opens);denied=false;RunControl cancelled=new RunControl();cancelled.cancel();assertThrows(Exception.class,()->ProjectDocumentImport.read(new AndroidProjectDocument(app,selectedUri,cancelled),cancelled));assertEquals(0,opens);assertThrows(SecurityException.class,()->new AndroidProjectDocument(app,Uri.fromFile(file),new RunControl()));}
}
